import { useEffect, useState } from 'react';
import { makeStyles } from '@mui/styles';
import Moment from 'react-moment';
import 'moment/locale/it';
import MuiTooltip from '@mui/material/Tooltip';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import Typography from '@mui/material/Typography';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Avatar from '@mui/material/Avatar';
import Chip from '@mui/material/Chip';
import Divider from '@mui/material/Divider';
import Box from '@mui/material/Box';
import Grid from '@mui/material/Grid';
import Card from '@mui/material/Card';
import Paper from '@mui/material/Paper';
import CircularProgress from '@mui/material/CircularProgress';
import CakeIcon from '@mui/icons-material/Cake';
import EventIcon from '@mui/icons-material/Event';
import SportsIcon from '@mui/icons-material/Sports';
import SportsSoccerIcon from '@mui/icons-material/SportsSoccer';
import StarIcon from '@mui/icons-material/Star';
import useRefereeDetails from '../../hooks/useRefereeDetails';

const OUTCOME = {
  V: { color: '#4caf50', label: 'Vittoria' },
  N: { color: '#9e9e9e', label: 'Pareggio' },
  S: { color: '#CA2331', label: 'Sconfitta' },
};

const PHOTO_BASE = 'https://www.archiviorossoblu.it/images/arbitri/';

const validDate = (d) => !!d && !d.startsWith('0000');

// "2008/03/22 Sampdoria 1-1 Cagliari" o "2007-12-05 Roma 2-0 Cagliari"
const parseFirstMatch = (str) => {
  const m = String(str || '').match(/^(\d{4})[/-](\d{2})[/-](\d{2})\s*(.*)$/);
  return m ? { date: `${m[1]}-${m[2]}-${m[3]}`, game: m[4] || null } : null;
};

const useStyles = makeStyles((theme) => ({
  title: {
    borderTop: '4px solid #CA2331',
    backgroundColor: '#082D68',
    color: '#F0C040',
    padding: theme.spacing(1.5, 2, 1),
  },
  sectionLabel: {
    fontSize: '0.65rem !important',
    fontWeight: '800 !important',
    letterSpacing: '0.08em !important',
    textTransform: 'uppercase',
    color: `${theme.palette.primary.main} !important`,
    padding: theme.spacing(1.5, 0, 0.5),
  },
  header: {
    fontSize: '0.72rem !important',
    fontWeight: '700 !important',
    color: '#082D68 !important',
    padding: '4px 8px !important',
    backgroundColor: '#fff !important',
  },
  row: {
    '&:hover': { backgroundColor: theme.palette.action.hover },
  },
  cell: {
    padding: '4px 8px !important',
    fontSize: '0.78rem !important',
  },
  avatarBlue: {
    width: '22px !important',
    height: '22px !important',
    fontSize: '0.6rem !important',
    fontWeight: '700 !important',
    backgroundColor: '#082D68 !important',
    color: '#fff !important',
  },
  infoRow: {
    display: 'flex',
    alignItems: 'center',
    flexWrap: 'wrap',
    gap: theme.spacing(1),
    padding: theme.spacing(0.5, 0),
  },
  panelCard: {
    padding: theme.spacing(2),
    height: '100%',
    boxSizing: 'border-box',
  },
  statRow: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: theme.spacing(0.75, 0),
    borderBottom: '1px solid rgba(0,0,0,0.06)',
    '&:last-child': { borderBottom: 'none' },
  },
  statLabel: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(0.75),
    fontSize: '0.8rem',
    color: 'rgba(0,0,0,0.6)',
  },
  statValue: {
    fontWeight: '700 !important',
    fontSize: '1.1rem !important',
    color: '#082D68 !important',
  },
  dot: {
    display: 'inline-block',
    width: 12,
    height: 12,
    borderRadius: '50%',
    flexShrink: 0,
  },
}));

function outcomeChip(outcome) {
  if (!outcome) return <Typography style={{ fontSize: '0.72rem', color: 'rgba(0,0,0,0.35)' }}>—</Typography>;
  return (
    <MuiTooltip title={OUTCOME[outcome].label} arrow>
      <Chip
        label={outcome}
        size="small"
        style={{ fontSize: '0.65rem', height: 20, minWidth: 28, fontWeight: 700, backgroundColor: OUTCOME[outcome].color, color: '#fff' }}
      />
    </MuiTooltip>
  );
}

/**
 * Modale di dettaglio arbitro: anagrafica, bilancio del Cagliari con
 * quell'arbitro e tutte le partite dirette (scrollabili, data decrescente).
 *
 * @param {object|null} referee  riga della lista arbitri ({ id, name, surname, ... }); null = chiusa
 */
export default function RefereeReport({ referee, handleClose }) {
  const classes = useStyles();
  const { loading, data, matches, totals } = useRefereeDetails(referee?.id);
  const [coords, setCoords] = useState(null);
  const [mapLoading, setMapLoading] = useState(false);

  const info = data || referee || {};
  const birthday = info.date || info.birthday;
  const birthplace = info.birthplace;

  useEffect(() => {
    if (!referee || !birthplace) { setCoords(null); return; }
    let isMounted = true;
    setCoords(null);
    setMapLoading(true);
    fetch(`https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(`${birthplace}, Italia`)}&format=json&limit=1`, {
      headers: { 'Accept-Language': 'it' },
    })
      .then(r => r.json())
      .then(results => {
        if (!isMounted) return;
        if (results?.[0]) setCoords({ lat: parseFloat(results[0].lat), lon: parseFloat(results[0].lon) });
        setMapLoading(false);
      })
      .catch(() => { if (isMounted) setMapLoading(false); });
    return () => { isMounted = false; };
  }, [referee, birthplace]);

  if (!referee) return null;

  const firstMatch = parseFirstMatch(data?.firstMatch);
  const winPct = totals?.played ? Math.round((totals.V / totals.played) * 100) : 0;
  const team = (name) => (
    <span style={{ fontWeight: name === 'Cagliari' ? 700 : 400, color: name === 'Cagliari' ? '#082D68' : 'inherit' }}>{name}</span>
  );

  return (
    <Dialog
      open
      onClose={handleClose}
      scroll="paper"
      fullWidth
      maxWidth="md"
      aria-labelledby="referee-dialog-title"
    >
      <DialogTitle id="referee-dialog-title" className={classes.title}>
        <Typography style={{ fontWeight: 700, fontSize: '1rem', color: '#F0C040' }}>
          Dettagli Arbitro
        </Typography>
      </DialogTitle>
      <DialogContent style={{ padding: 16 }}>
        <Grid container spacing={2} style={{ marginBottom: 16 }} alignItems="stretch">
          {/* Anagrafica + bilancio del Cagliari */}
          <Grid item xs={12} sm={birthplace ? 6 : 12}>
            <Card className={classes.panelCard} elevation={1}>
              <Box display="flex" alignItems="center" gap={2} mb={1.5}>
                <Avatar
                  src={data?.photo ? `${PHOTO_BASE}${data.photo}` : undefined}
                  alt={`${info.name || ''} ${info.surname || ''}`.trim()}
                  style={{ width: 64, height: 64, border: '3px solid #082D68', backgroundColor: '#F0C040', color: '#082D68', flexShrink: 0 }}
                >
                  <SportsIcon style={{ fontSize: 34 }} />
                </Avatar>
                <Box>
                  <Typography style={{ fontWeight: 700, fontSize: '1rem', color: '#082D68' }}>
                    {info.name} {info.surname}
                  </Typography>
                  <Chip label="Arbitro" size="small" style={{ backgroundColor: '#F0C040', color: '#082D68', fontWeight: 700, fontSize: '0.65rem', height: 20 }} />
                </Box>
              </Box>
              <Divider style={{ marginBottom: 8 }} />
              <div className={classes.infoRow}>
                <Avatar style={{ width: 22, height: 22, fontSize: '0.6rem', backgroundColor: '#CA2331', color: '#fff' }}>
                  <CakeIcon style={{ fontSize: 13 }} />
                </Avatar>
                <Box>
                  <Typography style={{ fontSize: '0.82rem', color: 'rgba(0,0,0,0.6)' }}>
                    {validDate(birthday) ? <Moment locale="it" format="LL">{birthday}</Moment> : '—'}
                  </Typography>
                  {birthplace && (
                    <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.45)' }}>{birthplace}</Typography>
                  )}
                </Box>
              </div>

              <Divider style={{ margin: '8px 0 0' }} />
              <Typography className={classes.sectionLabel}>Bilancio del Cagliari</Typography>
              {loading || !totals ? (
                <Box display="flex" justifyContent="center" py={3}><CircularProgress size={24} /></Box>
              ) : (
                <Box mt={1}>
                  <div className={classes.statRow}>
                    <span className={classes.statLabel}><EventIcon style={{ fontSize: 16, color: '#082D68' }} /> Partite</span>
                    <Typography className={classes.statValue}>{matches.length}</Typography>
                  </div>
                  {['V', 'N', 'S'].map(k => (
                    <div className={classes.statRow} key={k}>
                      <span className={classes.statLabel}>
                        <span className={classes.dot} style={{ backgroundColor: OUTCOME[k].color }} />
                        {k === 'V' ? 'Vittorie' : k === 'N' ? 'Pareggi' : 'Sconfitte'}
                      </span>
                      <Typography className={classes.statValue} style={{ color: OUTCOME[k].color }}>{totals[k]}</Typography>
                    </div>
                  ))}
                  <div className={classes.statRow}>
                    <span className={classes.statLabel}><SportsSoccerIcon style={{ fontSize: 16, color: '#CA2331' }} /> Gol fatti / subiti</span>
                    <Typography className={classes.statValue}>{totals.gf} – {totals.gs}</Typography>
                  </div>
                  <div className={classes.statRow}>
                    <span className={classes.statLabel}>% vittorie</span>
                    <Typography className={classes.statValue} style={{ color: winPct >= 50 ? '#2e7d32' : '#b71c1c' }}>{winPct}%</Typography>
                  </div>
                  {firstMatch && (
                    <div className={classes.statRow} style={{ alignItems: 'flex-start' }}>
                      <span className={classes.statLabel} style={{ paddingTop: 2 }}>
                        <StarIcon style={{ fontSize: 16, color: '#F0C040' }} /> Prima partita
                      </span>
                      <Box style={{ textAlign: 'right' }}>
                        <Typography style={{ fontSize: '0.82rem', fontWeight: 700, color: '#082D68' }}>
                          <Moment locale="it" format="LL">{firstMatch.date}</Moment>
                        </Typography>
                        {firstMatch.game && (
                          <Typography style={{ fontSize: '0.72rem', color: 'rgba(0,0,0,0.5)', fontStyle: 'italic', marginTop: 1 }}>
                            {firstMatch.game}
                          </Typography>
                        )}
                      </Box>
                    </div>
                  )}
                </Box>
              )}
            </Card>
          </Grid>

          {/* Mappa del luogo di nascita */}
          {birthplace && (
            <Grid item xs={12} sm={6} style={{ display: 'flex' }}>
              <Card elevation={1} style={{ flex: 1, overflow: 'hidden', padding: 0, minHeight: 240, display: 'flex', flexDirection: 'column' }}>
                <Box style={{ padding: '8px 12px', borderBottom: '1px solid rgba(0,0,0,0.08)' }}>
                  <Typography style={{ fontSize: '0.82rem', color: 'rgba(0,0,0,0.6)' }}>{birthplace}</Typography>
                </Box>
                {mapLoading ? (
                  <Box display="flex" alignItems="center" justifyContent="center" style={{ flex: 1 }} minHeight={160}>
                    <CircularProgress size={24} />
                  </Box>
                ) : coords ? (
                  <iframe
                    title="birthplace-map"
                    width="100%"
                    style={{ flex: 1, display: 'block', minHeight: 160, border: 0 }}
                    frameBorder="0"
                    scrolling="no"
                    src={`https://www.openstreetmap.org/export/embed.html?bbox=${coords.lon - 0.8},${coords.lat - 0.6},${coords.lon + 0.8},${coords.lat + 0.6}&layer=mapnik&marker=${coords.lat},${coords.lon}`}
                  />
                ) : (
                  <Box display="flex" alignItems="center" justifyContent="center" style={{ flex: 1 }} minHeight={160}>
                    <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.35)' }}>Posizione non disponibile</Typography>
                  </Box>
                )}
              </Card>
            </Grid>
          )}
        </Grid>

        {/* Tutte le partite dirette, scrollabili */}
        <Typography className={classes.sectionLabel}>
          Partite dirette{!loading && matches.length ? ` (${matches.length})` : ''}
        </Typography>
        <TableContainer component={Paper} elevation={0} style={{ border: '1px solid rgba(0,0,0,0.08)', borderRadius: 8, maxHeight: 360 }}>
          <Table size="small" stickyHeader>
            <TableHead>
              <TableRow>
                <TableCell className={classes.header}>Data</TableCell>
                <TableCell className={classes.header}>Stagione</TableCell>
                <TableCell className={classes.header}>Serie</TableCell>
                <TableCell className={classes.header} align="center">G.</TableCell>
                <TableCell className={classes.header}>Partita</TableCell>
                <TableCell className={classes.header} align="center">Esito</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={6} align="center"><CircularProgress size={24} style={{ margin: 12 }} /></TableCell>
                </TableRow>
              ) : matches.length > 0 ? matches.map((m) => (
                <TableRow key={m.id} className={classes.row}>
                  <TableCell className={classes.cell} style={{ whiteSpace: 'nowrap' }}>
                    {validDate(m.date) ? <Moment locale="it" format="DD/MM/YYYY">{m.date.slice(0, 10)}</Moment> : '—'}
                  </TableCell>
                  <TableCell className={classes.cell} style={{ whiteSpace: 'nowrap' }}>{m.season?.year || '—'}</TableCell>
                  <TableCell className={classes.cell}>
                    {m.season?.league && (
                      <MuiTooltip title={`Serie ${m.season.league}`} arrow><Avatar className={classes.avatarBlue}>{m.season.league}</Avatar></MuiTooltip>
                    )}
                  </TableCell>
                  <TableCell className={classes.cell} align="center">
                    {m.Spareggio === 'Y'
                      ? <MuiTooltip title={m.DescrizioneSpareggio || 'Spareggio'} arrow><span>Sp.</span></MuiTooltip>
                      : (m.day ? `${m.day}ª` : '—')}
                  </TableCell>
                  <TableCell className={classes.cell}>
                    {team(m.home)} <b>{m.played === 'Y' ? `${m.gh}-${m.ga}` : 'vs'}</b> {team(m.away)}
                  </TableCell>
                  <TableCell className={classes.cell} align="center">{outcomeChip(m.outcome)}</TableCell>
                </TableRow>
              )) : (
                <TableRow>
                  <TableCell colSpan={6} align="center">
                    <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.45)', padding: '8px 0' }}>Nessuna partita in archivio</Typography>
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClose} color="primary" size="small">Chiudi</Button>
      </DialogActions>
    </Dialog>
  );
}
