import { useEffect, useState } from 'react';
import * as ARBApi from '../utils/ARBApi';

// Esito dal punto di vista del Cagliari: 'V' | 'N' | 'S' | null (non giocata)
export function matchOutcome(m) {
  if (m.played !== 'Y') return null;
  const gh = parseInt(m.gh, 10);
  const ga = parseInt(m.ga, 10);
  if (isNaN(gh) || isNaN(ga)) return null;
  const ours = m.home === 'Cagliari' ? gh : ga;
  const theirs = m.home === 'Cagliari' ? ga : gh;
  return ours > theirs ? 'V' : ours < theirs ? 'S' : 'N';
}

// Chiave di ordinamento cronologico. Le partite storiche senza data
// ("0000-00-00") vengono collocate in base a stagione e giornata.
function chronoKey(m) {
  const t = m.date && !m.date.startsWith('0000') ? Date.parse(m.date.replace(' ', 'T')) : NaN;
  if (!isNaN(t)) return t;
  const startYear = parseInt(String(m.season?.year || '').slice(0, 4), 10);
  if (isNaN(startYear)) return 0;
  return Date.UTC(startYear, 7, 1) + (parseInt(m.day, 10) || 0) * 7 * 24 * 3600 * 1000;
}

/**
 * Carica il dettaglio di un arbitro da refereeDetails.php?id=…:
 * anagrafica + tutte le partite del Cagliari dirette, ordinate per data
 * decrescente, con stagione, esito e bilancio complessivo.
 *
 * @param {string|number|null} refereeId  null/undefined = nessun caricamento
 * @returns {{ loading: boolean, data: object|null, matches: Array, totals: object }}
 */
export default function useRefereeDetails(refereeId) {
  const [state, setState] = useState({ loading: false, data: null, matches: [], totals: null });

  useEffect(() => {
    if (!refereeId) {
      setState({ loading: false, data: null, matches: [], totals: null });
      return undefined;
    }
    let isMounted = true;
    setState({ loading: true, data: null, matches: [], totals: null });

    Promise.all([
      ARBApi.getAllByID('refereeDetails', refereeId),
      ARBApi.getAll('seasons'),
    ]).then(([res, seasons]) => {
      if (!isMounted) return;
      const seasonById = {};
      (Array.isArray(seasons) ? seasons : []).forEach(s => { seasonById[s.id] = { year: s.year, league: s.league }; });

      const matches = (res?.matches || [])
        .map(m => ({ ...m, season: seasonById[m.ID_S] || null, outcome: matchOutcome(m) }))
        .sort((a, b) => chronoKey(b) - chronoKey(a));

      const totals = matches.reduce((acc, m) => {
        if (!m.outcome) return acc;
        acc[m.outcome]++;
        const gh = parseInt(m.gh, 10);
        const ga = parseInt(m.ga, 10);
        acc.gf += m.home === 'Cagliari' ? gh : ga;
        acc.gs += m.home === 'Cagliari' ? ga : gh;
        return acc;
      }, { V: 0, N: 0, S: 0, gf: 0, gs: 0 });
      totals.played = totals.V + totals.N + totals.S;

      setState({ loading: false, data: res?.data || null, matches, totals });
    }).catch(() => {
      if (isMounted) setState({ loading: false, data: null, matches: [], totals: null });
    });

    return () => { isMounted = false; };
  }, [refereeId]);

  return state;
}
