// "1978-05-16" (anche con orario) -> "16/05/1978" (senza passare da Date, per evitare scarti di fuso orario)
function formatDate(iso) {
  if (!iso || iso.startsWith('0000')) return '—';
  const [y, m, d] = iso.slice(0, 10).split('-');
  return y && m && d ? `${d}/${m}/${y}` : '—';
}

const RANK_COLORS = { 1: '#F0C040', 2: '#B0BEC5', 3: '#CD7F32' };

export default function RefereesPage() {
  const classes = useStyles();
  const [referees, setReferees] = useState([]);
  const [loading, setLoading] = useState(true);
  const [orderBy, setOrderBy] = useState('appareances');
  const [orderDir, setOrderDir] = useState('desc');
  const [query, setQuery] = useState('');
  const [page, setPage] = useState(0);
  const [selectedReferee, setSelectedReferee] = useState(null);
  const rowsPerPage = 25;

  useEffect(() => {
    let isMounted = true;
    ARBApi.getAll('referees').then((list) => {
      if (!isMounted) return;
      const rows = (Array.isArray(list) ? list : []).map(r => ({ ...r, appareances: parseInt(r.appareances, 10) || 0 }));
      // Posizione nella classifica presenze: a parità di partite, stessa posizione
      const byApps = [...rows].sort((a, b) => b.appareances - a.appareances);
      byApps.forEach((r, i) => {
        r.rank = i > 0 && r.appareances === byApps[i - 1].appareances ? byApps[i - 1].rank : i + 1;
      });
      setReferees(rows);
      setLoading(false);
    });
    return () => { isMounted = false; };
  }, []);

  const handleSort = (col) => {
    if (orderBy === col) {
      setOrderDir(d => d === 'asc' ? 'desc' : 'asc');
    } else {
      setOrderBy(col);
      setOrderDir(col === 'appareances' ? 'desc' : 'asc');
    }
    setPage(0);
  };

  const handleQuery = (q) => { setQuery(q); setPage(0); };

  const byName = (a, b) => (`${a.surname} ${a.name}`).localeCompare(`${b.surname} ${b.name}`);
  const sorted = [...referees].sort((a, b) => {
    const mul = orderDir === 'asc' ? 1 : -1;
    if (orderBy === 'appareances') return mul * (a.appareances - b.appareances) || byName(a, b);
    return mul * byName(a, b);
  });

  let filtered = sorted;
  if (query) {
    const re = new RegExp(escapeRegExp(query), 'i');
    filtered = filtered.filter(r => re.test(r.name) || re.test(r.surname) || re.test(`${r.name} ${r.surname}`));
  }

  const paginated = filtered.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage);
  const totalMatches = referees.reduce((sum, r) => sum + r.appareances, 0);

  return (
    <div>
      <SEO
        title="Arbitri"
        description="Tutti gli arbitri che hanno diretto il Cagliari Calcio: classifica per partite dirette, data e luogo di nascita."
        path="/cagliari-calcio/arbitri"
      />

      <Card className={classes.navCard}>
        <div className={classes.navHeader}>
          <Sidebar iconColor="#F0C040" />
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, flex: 1 }}>
            <img
              src="https://www.archiviorossoblu.it/images/sun-gold-sella-bg.png"
              alt="logo"
              title="ArchivioRossoBlu"
              style={{ width: 80, height: 80, flexShrink: 0 }}
            />
            <Typography component="a" href="/cagliari-calcio" className={classes.brand} style={{ flex: 'none' }}>
              <span className="brand-short" title="ArchivioRossoBlu">ARB</span>
              <span className="brand-full">ArchivioRossoBlu</span>
            </Typography>
          </div>
          <YouTubeLink />
          <ShareButtons />
          <Chip label="Arbitri" size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
        </div>
        <Divider />
      </Card>

      <Box p={2}>
        <Breadcrumb items={[{ label: 'Home', href: '/cagliari-calcio' }, { label: 'Arbitri' }]} />
        <Grid container spacing={2}>
          <Grid item xs={12}>
            <Card className={classes.tableCard}>
              <CardHeader
                avatar={
                  <Chip label={loading ? '…' : filtered.length} size="small"
                    style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
                }
                title="Arbitri della storia"
                subheader="Cagliari Calcio — clicca su una riga per i dettagli"
              />
              <Divider />

              <Box style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '8px 12px', flexWrap: 'wrap' }}>
                <div className={classes.searchBar}>
                  <SearchIcon style={{ color: 'rgba(8,45,104,0.4)', fontSize: '1.1rem' }} />
                  <InputBase
                    placeholder="Cerca…"
                    value={query}
                    onChange={e => handleQuery(e.target.value)}
                    inputProps={{ style: { fontSize: '0.82rem', width: 140 } }}
                  />
                </div>
                {!loading && (
                  <>
                    <Chip size="small" label={`${referees.length} arbitri`}
                      style={{ fontSize: '0.65rem', height: 22, fontWeight: 700, backgroundColor: 'rgba(8,45,104,0.08)', color: '#082D68' }} />
                    <Chip size="small" label={`${totalMatches} partite dirette`}
                      style={{ fontSize: '0.65rem', height: 22, fontWeight: 700, backgroundColor: 'rgba(8,45,104,0.08)', color: '#082D68' }} />
                  </>
                )}
              </Box>

              <CardContent style={{ padding: 0 }}>
                <TableContainer>
                  <Table stickyHeader size="small">
                    <TableHead>
                      <TableRow>
                        <TableCell className={classes.header} align="center">#</TableCell>
                        <TableCell className={classes.header}>
                          <TableSortLabel active={orderBy === 'name'} direction={orderBy === 'name' ? orderDir : 'asc'} onClick={() => handleSort('name')}>
                            Arbitro
                          </TableSortLabel>
                        </TableCell>
                        <TableCell className={classes.header} align="center">
                          <TableSortLabel active={orderBy === 'appareances'} direction={orderBy === 'appareances' ? orderDir : 'desc'} onClick={() => handleSort('appareances')}>
                            Partite
                          </TableSortLabel>
                        </TableCell>
                        <TableCell className={classes.header}>Nato il</TableCell>
                        <TableCell className={classes.header}>Luogo di nascita</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {loading ? (
                        Array.from({ length: 10 }).map((_, i) => (
                          <TableRow key={i}>
                            <TableCell colSpan={5}>
                              <Skeleton animation="wave" height={36} />
                            </TableCell>
                          </TableRow>
                        ))
                      ) : paginated.length === 0 ? (
                        <TableRow>
                          <TableCell colSpan={5} align="center">
                            <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.45)' }}>Nessun arbitro trovato</Typography>
                          </TableCell>
                        </TableRow>
                      ) : paginated.map((ref) => (
                        <TableRow key={ref.id} className={classes.row} onClick={() => setSelectedReferee(ref)}>
                          <TableCell className={classes.cell} align="center" style={{ width: 48 }}>
                            <Typography style={{
                              fontSize: '0.78rem',
                              fontWeight: 700,
                              color: RANK_COLORS[ref.rank] ? '#082D68' : 'rgba(0,0,0,0.45)',
                              backgroundColor: RANK_COLORS[ref.rank] || 'transparent',
                              borderRadius: 10,
                              padding: '0 6px',
                              display: 'inline-block',
                              minWidth: 22,
                            }}>
                              {ref.rank}
                            </Typography>
                          </TableCell>
                          <TableCell className={classes.cell}>
                            <Typography style={{ fontSize: '0.82rem', fontWeight: 600 }}>
                              {ref.surname} {ref.name}
                            </Typography>
                          </TableCell>
                          <TableCell className={classes.cell} align="center">
                            <Chip label={ref.appareances} size="small" color="primary" style={{ fontSize: '0.65rem', height: 20, fontWeight: 700, minWidth: 28 }} />
                          </TableCell>
                          <TableCell className={classes.cell}>
                            <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.55)' }}>
                              {formatDate(ref.birthday)}
                            </Typography>
                          </TableCell>
                          <TableCell className={classes.cell}>
                            <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.55)' }}>
                              {ref.birthplace || '—'}
                            </Typography>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                    <TableFooter>
                      <TableRow>
                        <TablePagination
                          colSpan={5}
                          count={filtered.length}
                          rowsPerPage={rowsPerPage}
                          rowsPerPageOptions={[rowsPerPage]}
                          page={page}
                          onPageChange={(_, newPage) => setPage(newPage)}
                          ActionsComponent={TablePaginationActions}
                          labelDisplayedRows={({ from, to, count }) => `${from}–${to} di ${count}`}
                        />
                      </TableRow>
                    </TableFooter>
                  </Table>
                </TableContainer>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      </Box>

      <RefereeReport
        referee={selectedReferee}
        handleClose={() => setSelectedReferee(null)}
      />

      <Footer />
    </div>
  );
}
